static constexpr int GOLDEN_COUNT = 72;

int main() {
    int passed = 0;
    int failed = 0;

    for (int i = 0; i < GOLDEN_COUNT; ++i) {
        DatecsPacket pkt;
        DatecsError err = DatecsPacketParser::parse(GOLDEN[i].data, GOLDEN[i].len, pkt);
        if (err == DatecsError::NoErr) {
            ++passed;
        } else {
            std::printf("FAIL frame[%02d]: err=%d len=%u\n",
                        i, static_cast<int>(err), (unsigned)GOLDEN[i].len);
            ++failed;
        }
    }

    std::printf("GOLDEN_FRAMES %d/%d\n", passed, GOLDEN_COUNT);
    if (failed > 0 || passed != GOLDEN_COUNT) {
        return 1;
    }
    std::printf("GOLDEN_FRAMES OK %d\n", passed);
    return 0;
}
